	public List<MCPanel> getMCPanels(){
		List<MCPanel> ret = super.getMCPanels();
		ret.add(TopPanel);
		ret.add(FoldPanel);
		ret.add(Tab1Panel);
		ret.add(Tab2Panel);
		ret.add(CndPanel);
		ret.add(Cnd2Panel);
		ret.add(TtlPanel);
		ret.add(InptTtlPanel);
		ret.add(WkTtlPanel);
		ret.add(AlcTtlPanel);
		ret.add(LPnlPanel);
		ret.add(CtrlPanel);
		ret.add(DispRsltPanel);
		ret.add(RsltTabPanel);
		ret.add(DispRslt2Panel);
		ret.add(DispRslt3Panel);
		ret.add(DispRslt4Panel);
		ret.add(DispRslt5Panel);
		return ret;
	}

